#include <stdio.h>
#include <string.h>

#define MAXN 1000001

int F[MAXN];
long long prefix[MAXN];
int is_prime[MAXN];

int main() {
    memset(is_prime, 1, sizeof(is_prime));
    is_prime[0] = is_prime[1] = 0;
    for (int i = 2; (long long)i * i < MAXN; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j < MAXN; j += i)
                is_prime[j] = 0;
        }
    }
    for (int p = 2; p < MAXN; p++) {
        if (is_prime[p]) {
            for (int j = p; j < MAXN; j += p) {
                int temp = j, count = 0;
                while (temp % p == 0) {
                    temp /= p;
                    count++;
                }
                F[j] += count;
            }
        }
    }
    prefix[0] = 0;
    for (int i = 1; i < MAXN; i++)
        prefix[i] = prefix[i - 1] + F[i];
    int T;
    scanf("%d", &T);
    while (T--) {
        int A, B;
        scanf("%d %d", &A, &B);
        printf("%lld\n", prefix[B] - prefix[A - 1]);
    }
    return 0;
}

